#include <bits/stdc++.h>using namespace std;#define int long longinline void fmx(int &a,int b){ if(a<b) a=b;}#define go(i,a,b) for(int i=a;i<=b;i++)#define og(i,a,b) for(int i=b;i>=a;i--)#define all() a.begin() + 1,a.begin() + n + 1int T,n; void O_o(){    cin >> n;    vector<int> a(n + 1);    int tot = 0;    for(int i=1;i<=n;i++){        cin >> a[i];        tot += a[i];    }    set<int> st;    for(int i=1;i<=n;i++){        vector<int> b = a;        int cur = i;        int rem = tot;        int win = -1;                while(rem > 0){            while(b[cur] == 0){                cur = (cur % n) + 1;            }            b[cur]--;            rem--;            if(rem == 0){                win = cur;                break;            }            cur = (cur % n) + 1;        }        st.insert(win);    }    cout << st.size() << '\n';} signed main(){    ios::sync_with_stdio(false);    cin.tie(nullptr);cout.tie(nullptr);    cin >> T;    while(T--)O_o();}